CREATE OR REPLACE FUNCTION public.create_voluntary_challenge(_title text, _metric text, _start date, _end date, _friends uuid[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE cid uuid; uid uuid := auth.uid(); fid uuid; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF length(trim(_title)) NOT BETWEEN 1 AND 120 OR _metric NOT IN ('pass','days') OR _end < _start THEN RAISE EXCEPTION 'Invalid challenge'; END IF; FOREACH fid IN ARRAY coalesce(_friends, ARRAY[]::uuid[]) LOOP IF fid = uid OR NOT EXISTS (SELECT 1 FROM public.friendships f WHERE f.status='accepted' AND ((f.user_id=uid AND f.friend_id=fid) OR (f.friend_id=uid AND f.user_id=fid))) THEN RAISE EXCEPTION 'Only accepted friends can be invited'; END IF; END LOOP; INSERT INTO public.friend_challenges(title,metric,start_date,end_date,created_by) VALUES(trim(_title),_metric,_start,_end,uid) RETURNING id INTO cid; INSERT INTO public.friend_challenge_participants(challenge_id,user_id,status) VALUES(cid,uid,'accepted'); INSERT INTO public.friend_challenge_participants(challenge_id,user_id,status,invited_by) SELECT cid,x,'pending',uid FROM (SELECT DISTINCT unnest(coalesce(_friends,ARRAY[]::uuid[])) x) f; RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.create_voluntary_challenge(text,text,date,date,uuid[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_voluntary_challenge(text,text,date,date,uuid[]) TO authenticated;
DROP POLICY "Creator or self can add participants" ON public.friend_challenge_participants;
CREATE POLICY "Creator invites pending friends or joins self" ON public.friend_challenge_participants FOR INSERT TO authenticated WITH CHECK ((user_id=auth.uid() AND status='accepted' AND EXISTS(SELECT 1 FROM public.friend_challenges c WHERE c.id=challenge_id AND c.created_by=auth.uid())) OR (status='pending' AND invited_by=auth.uid() AND EXISTS(SELECT 1 FROM public.friend_challenges c WHERE c.id=challenge_id AND c.created_by=auth.uid()) AND EXISTS(SELECT 1 FROM public.friendships f WHERE f.status='accepted' AND ((f.user_id=auth.uid() AND f.friend_id=friend_challenge_participants.user_id) OR (f.friend_id=auth.uid() AND f.user_id=friend_challenge_participants.user_id)))));
CREATE OR REPLACE FUNCTION public.voluntary_challenge_standings(_challenge uuid) RETURNS TABLE(user_id uuid,nickname text,value bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.friend_challenges; BEGIN SELECT * INTO c FROM public.friend_challenges WHERE id=_challenge; IF c.id IS NULL OR c.metric NOT IN ('pass','days') OR NOT EXISTS(SELECT 1 FROM public.friend_challenge_participants p WHERE p.challenge_id=_challenge AND p.user_id=auth.uid() AND p.status='accepted') THEN RAISE EXCEPTION 'Join the challenge first'; END IF; RETURN QUERY WITH participants AS (SELECT p.user_id FROM public.friend_challenge_participants p WHERE p.challenge_id=_challenge AND p.status='accepted'), logs AS (SELECT w.user_id, to_jsonb(w) AS row, pr.plan_start_date::date AS plan_start FROM public.workout_completions w JOIN participants p ON p.user_id=w.user_id LEFT JOIN public.profiles pr ON pr.user_id=w.user_id UNION ALL SELECT a.user_id,x.row,a.plan_start_date::date FROM public.archived_plans a JOIN participants p ON p.user_id=a.user_id CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(a.completion_data)='array' THEN a.completion_data ELSE '[]'::jsonb END) x(row)), dated AS (SELECT l.user_id,l.row,CASE WHEN coalesce((l.row->>'week')::integer,0)=0 AND l.row->>'day' ~ '^\d{4}-\d{2}-\d{2}' THEN left(l.row->>'day',10)::date WHEN l.plan_start IS NOT NULL AND (l.row->>'week')::integer>0 THEN date_trunc('week',l.plan_start::timestamp)::date + (((l.row->>'week')::integer-1)*7) + CASE lower(split_part(regexp_replace(l.row->>'day','_[a-z0-9]+$','','i'),' ',1)) WHEN 'mån' THEN 0 WHEN 'måndag' THEN 0 WHEN 'tis' THEN 1 WHEN 'tisdag' THEN 1 WHEN 'ons' THEN 2 WHEN 'onsdag' THEN 2 WHEN 'tor' THEN 3 WHEN 'tors' THEN 3 WHEN 'torsdag' THEN 3 WHEN 'fre' THEN 4 WHEN 'fredag' THEN 4 WHEN 'lör' THEN 5 WHEN 'lördag' THEN 5 WHEN 'sön' THEN 6 WHEN 'söndag' THEN 6 ELSE 0 END ELSE (l.row->>'updated_at')::timestamptz AT TIME ZONE 'UTC' END::date AS day FROM logs l), valid AS (SELECT d.user_id,d.day FROM dated d WHERE d.day BETWEEN c.start_date AND c.end_date AND d.row->>'done'='true' AND (coalesce((d.row->>'logged_distance_km')::numeric,0)>0 OR EXISTS(SELECT 1 FROM jsonb_each_text(CASE WHEN jsonb_typeof(d.row->'logged_weights')='object' THEN d.row->'logged_weights' ELSE '{}'::jsonb END) w WHERE (w.key LIKE '__sets__%' AND w.value LIKE '%1%') OR (w.key LIKE '__cond_done__%' AND w.value='1')))) SELECT p.user_id,coalesce(pr.nickname,'Okänd')::text,CASE WHEN c.metric='days' THEN count(DISTINCT v.day) ELSE count(v.day) END FROM participants p LEFT JOIN public.profiles pr ON pr.user_id=p.user_id LEFT JOIN valid v ON v.user_id=p.user_id GROUP BY p.user_id,pr.nickname ORDER BY 3 DESC; END $$;
REVOKE ALL ON FUNCTION public.voluntary_challenge_standings(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.voluntary_challenge_standings(uuid) TO authenticated;